macro.command:
// True Resurrection — restore to life with full HP, remove all conditions
for (const target of workflow.targets) {
  const tActor = target.actor;
  if (!tActor) continue;
  const hp = tActor.system.attributes.hp;
  await tActor.update({
    "system.attributes.hp.value": hp.max,
    "system.attributes.hp.temp": 0,
    "system.attributes.death.success": 0,
    "system.attributes.death.failure": 0,
    "system.attributes.exhaustion": 0
  });
  const conditions = ["dead", "unconscious", "poisoned", "diseased", "cursed", "blinded", "deafened", "paralyzed", "stunned", "petrified", "prone"];
  for (const c of conditions) {
    await tActor.toggleStatusEffect(c, {active: false});
  }
  ChatMessage.create({
    content: `<strong>True Resurrection</strong>: ${target.name} is restored to life with full hit points. All wounds, poisons, diseases, and curses are lifted.`,
    speaker: ChatMessage.getSpeaker({ actor: workflow.actor })
  });
}
